import { AstroError, AstroErrorData } from "../core/errors/index.js";
export function getEnvFieldType(options) {
	const optional = options.optional ? options.default !== undefined ? false : true : false;
	let type;
	if (options.type === "enum") {
		type = options.values.map((v) => `'${v}'`).join(" | ");
	} else {
		type = options.type;
	}
	return `${type}${optional ? " | undefined" : ""}`;
}
const stringValidator = ({ max, min, length, url, includes, startsWith, endsWith }) => (input) => {
	if (typeof input !== "string") {
		return {
			ok: false,
			errors: ["type"]
		};
	}
	const errors = [];
	if (max !== undefined && !(input.length <= max)) {
		errors.push("max");
	}
	if (min !== undefined && !(input.length >= min)) {
		errors.push("min");
	}
	if (length !== undefined && !(input.length === length)) {
		errors.push("length");
	}
	if (url !== undefined && !URL.canParse(input)) {
		errors.push("url");
	}
	if (includes !== undefined && !input.includes(includes)) {
		errors.push("includes");
	}
	if (startsWith !== undefined && !input.startsWith(startsWith)) {
		errors.push("startsWith");
	}
	if (endsWith !== undefined && !input.endsWith(endsWith)) {
		errors.push("endsWith");
	}
	if (errors.length > 0) {
		return {
			ok: false,
			errors
		};
	}
	return {
		ok: true,
		value: input
	};
};
const numberValidator = ({ gt, min, lt, max, int }) => (input) => {
	const num = Number.parseFloat(input ?? "");
	if (isNaN(num)) {
		return {
			ok: false,
			errors: ["type"]
		};
	}
	const errors = [];
	if (gt !== undefined && !(num > gt)) {
		errors.push("gt");
	}
	if (min !== undefined && !(num >= min)) {
		errors.push("min");
	}
	if (lt !== undefined && !(num < lt)) {
		errors.push("lt");
	}
	if (max !== undefined && !(num <= max)) {
		errors.push("max");
	}
	if (int !== undefined) {
		const isInt = Number.isInteger(num);
		if (!(int ? isInt : !isInt)) {
			errors.push("int");
		}
	}
	if (errors.length > 0) {
		return {
			ok: false,
			errors
		};
	}
	return {
		ok: true,
		value: num
	};
};
const booleanValidator = (input) => {
	const bool = input === "true" ? true : input === "false" ? false : undefined;
	if (typeof bool !== "boolean") {
		return {
			ok: false,
			errors: ["type"]
		};
	}
	return {
		ok: true,
		value: bool
	};
};
const enumValidator = ({ values }) => (input) => {
	if (!(typeof input === "string" ? values.includes(input) : false)) {
		return {
			ok: false,
			errors: ["type"]
		};
	}
	return {
		ok: true,
		value: input
	};
};
function selectValidator(options) {
	switch (options.type) {
		case "string": return stringValidator(options);
		case "number": return numberValidator(options);
		case "boolean": return booleanValidator;
		case "enum": return enumValidator(options);
	}
}
export function validateEnvVariable(value, options) {
	const isOptional = options.optional || options.default !== undefined;
	if (isOptional && value === undefined) {
		return {
			ok: true,
			value: options.default
		};
	}
	if (!isOptional && value === undefined) {
		return {
			ok: false,
			errors: ["missing"]
		};
	}
	return selectValidator(options)(value);
}
/**
* Validates that `vite.envPrefix` doesn't match any environment variables declared
* with `access: "secret"` in `env.schema`. If it does, those secrets would be exposed
* by Vite in client-side bundles via `import.meta.env`, completely bypassing the
* `access: "secret"` protection.
*
* Throws an `AstroError` if conflicts are found.
*/
export function validateEnvPrefixAgainstSchema(config) {
	const schema = config.env.schema;
	const envPrefix = config.vite?.envPrefix;
	// No schema or using default prefix — nothing to validate
	if (Object.keys(schema).length === 0 || !envPrefix) {
		return;
	}
	const prefixes = Array.isArray(envPrefix) ? envPrefix : [envPrefix];
	const conflicts = [];
	for (const [key, options] of Object.entries(schema)) {
		if (options.access === "secret" && prefixes.some((prefix) => key.startsWith(prefix))) {
			conflicts.push(key);
		}
	}
	if (conflicts.length > 0) {
		throw new AstroError({
			...AstroErrorData.EnvPrefixConflictsWithSecret,
			message: AstroErrorData.EnvPrefixConflictsWithSecret.message(conflicts)
		});
	}
}
